# WRF Extreme Rainfall - 3 sub-layers with GHoA boundary filtering
# Each sub-layer is individually toggleable in the mapviewer legend

# Heavy Rainfall
LAYER
    INCLUDE "config/database.map"
    DATA "geom from (select g.id, r.f90_mm as rainfall_mm, g.cell as geom from wrf.grid_01dd g join wrf.extreme_rainfall r on g.id = r.grid_id where r.forecast_date = '%time%'::date and r.f90_mm > 0 and exists (select 1 from gha.admin0 a where a.geom && g.cell and ST_Intersects(g.cell, a.geom))) as subq using unique id using srid=4326"
    INCLUDE "shared/common-layer-properties.map"
    CLASS
        NAME "Heavy Rainfall"
        STYLE
            COLOR 175 238 238
            OUTLINECOLOR 175 238 238
        END
    END
    METADATA
        "wms_title" "WRF Heavy Rainfall"
        INCLUDE "shared/wms-layer-metadata.map"
    END
    NAME "wrf_extreme_heavy"
    VALIDATION
        "time" "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"
        "default_time" "2026-02-12"
    END
END

